1480: # Substantive prose: >= 120 words, or >= 40 words with at least one numbered answer at a
1481: # line start (**Q1.**, Q1., 1.).
1482: function Test-SubstantiveProse {
1483:     param([string]$Text)
1484:     $words = @(([string]$Text -split '\s+') | Where-Object { $_ }).Count
1485:     if ($words -ge 120) { return $true }
1486:     return ($words -ge 40 -and $Text -match '(?m)^\s*(\*\*Q[0-9]+\.\*\*|Q[0-9]+\.|[0-9]+\.)')
1487: }
